INTENT
Provide a public URL shortening service that issues short redirect links which anyone holding them may resolve, while refusing to create or serve links whose destination could be used for phishing or to reach internal network resources, and expiring links after a caller-settable lifetime that defaults to 30 days.

DESIGN
{
  "configuration": [
    {
      "default": "./links.db",
      "name": "LINKS_DB_PATH",
      "purpose": "Filesystem path to the SQLite database file. Tests and implementation both bind to this exact name; ':memory:' is accepted for ephemeral runs."
    },
    {
      "default": "127.0.0.1",
      "name": "LINKS_BIND_HOST",
      "purpose": "Interface the HTTP server binds to."
    },
    {
      "default": "8080",
      "name": "LINKS_BIND_PORT",
      "purpose": "TCP port the HTTP server binds to (TLS is terminated by the fronting proxy; the app speaks plain HTTP on this port)."
    },
    {
      "default": "https://short.example.com",
      "name": "LINKS_PUBLIC_BASE_URL",
      "purpose": "Origin used to build the 'short_url' field in create responses. Must be https and must not end with a trailing slash; a trailing slash is stripped at startup."
    },
    {
      "default": "30",
      "name": "LINKS_DEFAULT_EXPIRY_DAYS",
      "purpose": "expires_at offset applied when the caller omits expires_in_days."
    },
    {
      "default": "365",
      "name": "LINKS_MAX_EXPIRY_DAYS",
      "purpose": "Upper inclusive bound for caller-supplied expires_in_days; above this yields 400 expiry_out_of_range."
    },
    {
      "default": "2048",
      "name": "LINKS_MAX_URL_LENGTH",
      "purpose": "Maximum character length of the submitted destination URL, measured on the raw input string before normalization."
    },
    {
      "default": "7",
      "name": "LINKS_CODE_LENGTH",
      "purpose": "Number of base62 characters in a generated short code."
    },
    {
      "default": "5",
      "name": "LINKS_CODE_MAX_ATTEMPTS",
      "purpose": "Bounded retry count for UNIQUE-constraint collisions on the generated code before returning 503 code_generation_failed."
    },
    {
      "default": "20",
      "name": "LINKS_RATE_LIMIT_MAX",
      "purpose": "Maximum successful-or-attempted POST /links requests per client IP per window."
    },
    {
      "default": "60",
      "name": "LINKS_RATE_LIMIT_WINDOW_SECONDS",
      "purpose": "Length of the fixed rate-limit window in seconds; also the value returned in Retry-After (seconds remaining in the window, minimum 1)."
    },
    {
      "default": "false",
      "name": "LINKS_TRUST_PROXY_HEADER",
      "purpose": "When 'true', the client IP for rate limiting is taken from the last entry of X-Forwarded-For; otherwise the socket peer address is used."
    },
    {
      "default": "2000",
      "name": "LINKS_DNS_TIMEOUT_MS",
      "purpose": "Per-host timeout for A and AAAA resolution during validation; on timeout the destination is rejected."
    },
    {
      "default": "0",
      "name": "LINKS_DNS_CACHE_TTL_SECONDS",
      "purpose": "TTL for the internal resolution-result cache. Default 0 disables caching so redirect-time re-validation always sees current DNS (defeats rebinding)."
    },
    {
      "default": "false",
      "name": "LINKS_ALLOW_PRIVATE_DESTINATIONS",
      "purpose": "Test-only escape hatch; when 'true' the IP-range denylist is skipped. Must remain false in production."
    },
    {
      "default": "info",
      "name": "LINKS_LOG_LEVEL",
      "purpose": "Logging verbosity: debug, info, warn, error."
    }
  ],
  "data_model": [
    {
      "fields": [
        {
          "constraints": "PRIMARY KEY AUTOINCREMENT, internal only, never exposed in any response or URL.",
          "name": "id",
          "type": "INTEGER"
        },
        {
          "constraints": "NOT NULL, UNIQUE (uniqueness enforced here, not by a pre-insert SELECT); exactly LINKS_CODE_LENGTH base62 characters.",
          "name": "code",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL, length <= LINKS_MAX_URL_LENGTH, stores the normalized (punycode A-label host, lowercased host, userinfo absent, default port stripped) absolute http/https URL. Not unique: two callers shortening the same URL get two rows and two codes.",
          "name": "destination",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL, ISO-8601 UTC with 'Z' suffix, set by the service at insert.",
          "name": "created_at",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL, ISO-8601 UTC with 'Z' suffix, = created_at + (expires_in_days or LINKS_DEFAULT_EXPIRY_DAYS) days; comparison against now is a lexicographic string compare, valid because the format is fixed-width UTC.",
          "name": "expires_at",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL, client IP recorded for abuse triage; never returned by any endpoint.",
          "name": "creator_ip",
          "type": "TEXT"
        },
        {
          "constraints": "NOT NULL DEFAULT 0, incremented after the redirect response is written.",
          "name": "click_count",
          "type": "INTEGER"
        },
        {
          "constraints": "NULL until the first successful redirect, then ISO-8601 UTC.",
          "name": "last_clicked_at",
          "type": "TEXT"
        }
      ],
      "indexes": [
        "UNIQUE index on links(code) \u2014 created implicitly by the UNIQUE constraint; this is the hot redirect lookup 'SELECT destination, expires_at FROM links WHERE code = ?'. Without it every redirect is a full table scan.",
        "Index on links(expires_at) \u2014 supports the periodic purge 'DELETE FROM links WHERE expires_at <= ?'; without it the purge scans the whole table."
      ],
      "name": "links",
      "purpose": "One row per issued short link; the sole read path for redirects."
    },
    {
      "fields": [
        {
          "constraints": "Map key; source depends on LINKS_TRUST_PROXY_HEADER.",
          "name": "client_ip",
          "type": "string"
        },
        {
          "constraints": "Unix seconds, floor(now / LINKS_RATE_LIMIT_WINDOW_SECONDS) * window.",
          "name": "window_start_epoch",
          "type": "integer"
        },
        {
          "constraints": ">= 0; reset to 1 when window_start_epoch rolls over.",
          "name": "count",
          "type": "integer"
        }
      ],
      "indexes": [
        "Hash map keyed by client_ip \u2014 O(1) per request; entries whose window has elapsed are evicted lazily on access and by a sweep each window."
      ],
      "name": "rate_limit_buckets",
      "purpose": "In-process (non-persistent) map of client IP to fixed-window counter used by the creation rate limiter. Documented as a data structure, not a SQLite table, because it must not add a write to the hot creation path and is per-node by design."
    }
  ],
  "decisions": [
    {
      "choice": "SQLite with journal_mode=WAL, synchronous=NORMAL, busy_timeout=5000ms, single file at LINKS_DB_PATH.",
      "decision": "Datastore and concurrency mode",
      "rationale": "Deployment is single node and the redirect path is a single unique-index lookup, so WAL lets the click-count write proceed without blocking concurrent redirect reads \u2014 users never see a redirect stall behind an analytics update.",
      "rejected": [
        "Postgres: an extra network hop and an operational component for a workload that is one indexed read per request.",
        "SQLite in rollback-journal mode: writers block readers, so a burst of clicks would serialize redirects.",
        "In-memory only: the persistence acceptance criterion (one row per creation) could not be asserted across a restart."
      ]
    },
    {
      "choice": "410 Gone with error code link_expired for expired rows; 404 Not Found with error code not_found for codes that never existed or fail the alphabet check. The two are deliberately distinguishable.",
      "decision": "Response for an expired code, and whether it is distinguishable from a never-issued code",
      "rationale": "A holder of a link that stopped working gets an actionable answer ('this link expired') instead of a misleading 'never existed', and 410 tells crawlers to drop the URL. The disclosure is bounded: knowing a random 7-character base62 code once existed is worthless without the destination, which is never revealed, and codes are unguessable so this is not an enumeration oracle.",
      "rejected": [
        "Collapse both to 404: hides expiry from legitimate users and gives support no way to distinguish a typo from a lapsed link.",
        "410 for both: falsely asserts that an unissued code once existed.",
        "Return the destination or created_at on the 410 page: leaks the target of a link the caller may not be entitled to."
      ]
    },
    {
      "choice": "The 302 is written and flushed first; the UPDATE links SET click_count = click_count + 1, last_clicked_at = ? WHERE code = ? runs afterwards on a background task, and its failure is logged but never converts a successful redirect into a 500.",
      "decision": "Placement of the click-analytics write relative to the redirect response",
      "rationale": "Redirect latency is what a user feels, and a database hiccup must not break a working link; the cost is that counts are best-effort and may lose the last few increments on an unclean shutdown, which is acceptable for click analytics.",
      "rejected": [
        "Increment synchronously inside the request before responding: adds a write and a possible lock wait to every redirect and lets a datastore error break a valid link.",
        "Write one row per click to an events table: unbounded growth and a write amplification the acceptance criteria never ask for.",
        "Fire-and-forget with no logging: silent analytics loss with no way to detect it."
      ]
    },
    {
      "choice": "Enforced in application middleware on POST /links only, keyed by client IP (socket peer address, or the last X-Forwarded-For entry when LINKS_TRUST_PROXY_HEADER=true), fixed window of LINKS_RATE_LIMIT_WINDOW_SECONDS allowing LINKS_RATE_LIMIT_MAX requests; over-limit returns 429 with Retry-After set to the seconds remaining in the window and short-circuits before validation, DNS and any insert.",
      "decision": "Layer and key for rate limiting",
      "rationale": "Creation is unauthenticated, so IP is the only stable identity available, and enforcing it in-app means the limiter runs before DNS resolution \u2014 an abuser cannot use the service as a DNS amplifier or fill the table. Applying it in-app rather than only at the proxy also means the limit holds in tests and in local runs where no proxy exists.",
      "rejected": [
        "Proxy or WAF-only enforcement: invisible to the test suite and absent in single-binary deployments, so the criterion could not be verified.",
        "Rate limiting the redirect path: short links are meant to be shared widely and a viral link would be throttled for everyone behind one NAT.",
        "Token bucket in a shared store like Redis: an extra dependency for a single-node deployment; the fixed window's boundary burst of up to 2x is tolerable at these volumes.",
        "Keying by API key: creation is specified as unauthenticated, so there is no key to key on."
      ]
    },
    {
      "choice": "Parse, IDNA-normalize the host to its A-label, then resolve A and AAAA records via the system resolver with LINKS_DNS_TIMEOUT_MS; reject unless every returned address passes the range denylist. No socket is ever opened to the destination host or port at creation or at redirect time.",
      "decision": "How SSRF validation is performed without touching the destination",
      "rationale": "A user is never able to turn the shortener into a proxy that reaches cloud metadata or an internal admin panel, and metadata.google.internal is rejected purely from its resolved link-local answer with zero outbound connections to it \u2014 the exact behaviour the zero-connection test asserts.",
      "rejected": [
        "Fetch the URL to verify it is live or grab a title: makes the service a confirmed SSRF gadget and is explicitly forbidden.",
        "Check only the first

IMPLEMENTATION
