NXDOMAIN_HOSTS = {"nonexistent.invalid", "does-not-resolve.example"}


def _normalise_host(host):
    if not isinstance(host, str):
        return ""
    host = host.strip().strip("[]").rstrip(".").lower()
    try:
        host.encode("ascii")
    except UnicodeEncodeError:
        try:
            host = host.encode("idna").decode("ascii")
        except Exception:
            pass
    return host


@pytest.fixture(autouse=True)
def stub_network(monkeypatch, dns_map, outbound_connections):
    """No real DNS, no real sockets. Deterministic, offline, per test."""

    def addresses_for(host):
        key = _normalise_host(host)
        if key in NXDOMAIN_HOSTS:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        try:
            return [str(ipaddress.ip_address(key))]
        except ValueError:
            pass
        if key in dns_map:
            return list(dns_map[key])
        if not key:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        # Unmapped hosts are treated as ordinary public destinations so that
        # tests never depend on the machine's real resolver.
        return [PUBLIC_IP]

    def fake_getaddrinfo(host, port, family=0, type=0, proto=0, flags=0):
        results = []
        portnum = port if isinstance(port, int) else 0
        for addr in addresses_for(host):
            ip = ipaddress.ip_address(addr)
            if ip.version == 4:
                if family in (0, socket.AF_INET, socket.AF_UNSPEC):
                    results.append(
                        (socket.AF_INET, socket.SOCK_STREAM, 6, "", (str(ip), portnum))
                    )
            else:
                if family in (0, socket.AF_INET6, socket.AF_UNSPEC):
                    results.append(
                        (
                            socket.AF_INET6,
                            socket.SOCK_STREAM,
                            6,
                            "",
                            (str(ip), portnum, 0, 0),
                        )
                    )
        if not results:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        return results

    def fake_gethostbyname(host):
        for addr in addresses_for(host):
            if ipaddress.ip_address(addr).version == 4:
                return addr
        raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")

    def fake_gethostbyname_ex(host):
        v4 = [a for a in addresses_for(host) if ipaddress.ip_address(a).version == 4]
        if not v4:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        return (_normalise_host(host), [], v4)

    monkeypatch.setattr(socket, "getaddrinfo", fake_getaddrinfo)
    monkeypatch.setattr(socket, "gethostbyname", fake_gethostbyname)
    monkeypatch.setattr(socket, "gethostbyname_ex", fake_gethostbyname_ex)

    def blocked_connect(self, address, *args, **kwargs):
        outbound_connections.append(address)
        raise AssertionError(f"outbound connection attempted to {address!r}")

    def blocked_create_connection(address, *args, **kwargs):
        outbound_connections.append(address)
        raise AssertionError(f"outbound connection attempted to {address!r}")

    monkeypatch.setattr(socket.socket, "connect", blocked_connect)
    monkeypatch.setattr(socket.socket, "connect_ex", blocked_connect)
    monkeypatch.setattr(socket, "create_connection", blocked_create_connection)
    yield


@pytest.fixture
def make_client(monkeypatch, tmp_path):
    """Factory: make_client(LINKS_RATE_LIMIT_MAX='3') -> TestClient.

    Each client gets its own database file, its own freshly imported module
    graph, and the design's configuration defaults unless overridden.
    """
    opened = []

    def _make(**overrides):
        db_path = str(tmp_path / f"links-{len(opened)}.db")
        for key in list(os.environ):
            if key.startswith("LINKS_"):
                monkeypatch.delenv(key, raising=False)
        env = dict(DEFAULT_ENV)
        env["LINKS_DB_PATH"] = db_path
        env.update({k: str(v) for k, v in overrides.items()})
        for key, value in env.items():
            monkeypatch.setenv(key, value)
        module, app = load_app()
        manager = TestClient(app)
        client = manager.__enter__()
        opened.append(manager)
        client.app_module = module
        client.db = DB(db_path)
        client.db_path = db_path
        return client

    yield _make

    for manager in reversed(opened):
        try:
            manager.__exit__(None, None, None)
        except Exception:
            pass
    _purge_app_modules()


@pytest.fixture
def client(make_client):
    return make_client()


def find_code_generators(app_module):
    """Locate the short-code generator function inside the app's modules."""
    roots = {app_module.__name__.split(".")[0]}
    found = []
    for mod_name, mod in list(sys.modules.items()):
        if mod is None or mod_name.split(".")[0] not in roots:
            continue
        for attr in dir(mod):
            try:
                obj = getattr(mod, attr)
            except Exception:
                continue
            if not inspect.isfunction(obj):
                continue
            lowered = attr.lower()
            if "code" not in lowered:
                continue
            if not any(w in lowered for w in ("gen", "make", "new", "rand", "mint", "create")):
                continue
            try:
                sig = inspect.signature(obj)
            except (TypeError, ValueError):
                continue
            required = [
                p
                for p in sig.parameters.values()
                if p.default is p.empty
                and p.kind
                in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY)
            ]
            if len(required) > 1:
                continue
            found.append((mod, attr, obj))
    return found


def patch_code_generator(monkeypatch, app_module, side_effect_factory):
    """Replace the code generator everywhere it is bound.

    side_effect_factory receives the original function and returns the
    replacement.  Returns the original callable.
    """
    found = find_code_generators(app_module)
    if not found:
        pytest.fail(
            "No short-code generator function found in the application modules; "
            "collision retry cannot be exercised. Expected a module-level "
            "function whose name mentions 'code' and generation "
            "(e.g. generate_code)."
        )
    original = found[0][2]
    replacement = side_effect_factory(original)
    for mod, attr, obj in found:
        if obj is original:
            monkeypatch.setattr(mod, attr, replacement)
    return original
