from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from helpers import extract_code, has_error_token, parse_iso

PAST = "2001-01-01T00:00:00Z"


def test_default_expiry_is_thirty_days_after_creation(client):
    before = datetime.now(timezone.utc)
    resp = client.post("/links", json={"url": "https://example.com/a"})
    after = datetime.now(timezone.utc)

    assert resp.status_code == 201, resp.text
    expires_at = resp.json()["expires_at"]
    assert expires_at.endswith("Z"), f"expires_at is not UTC 'Z' form: {expires_at!r}"
    parsed = parse_iso(expires_at)
    assert before + timedelta(days=30) - timedelta(seconds=60) <= parsed
    assert parsed <= after + timedelta(days=30) + timedelta(seconds=60)


def test_expires_in_days_of_one_yields_an_expiry_one_day_out(client):
    before = datetime.now(timezone.utc)
    resp = client.post(
        "/links", json={"url": "https://example.com/a", "expires_in_days": 1}
    )
    after = datetime.now(timezone.utc)

    assert resp.status_code == 201, resp.text
    parsed = parse_iso(resp.json()["expires_at"])
    assert before + timedelta(days=1) - timedelta(seconds=60) <= parsed
    assert parsed <= after + timedelta(days=1) + timedelta(seconds=60)
    assert parsed < before + timedelta(days=2), "1 day was not honoured"


@pytest.mark.parametrize("value", [0, -1, 366, 100000])
