"},{"path":"tests/test_rate_limit.py","content":""""Creation rate limiting: over the limit is 429, and the limit is per key."""
from __future__ import annotations


def _create(client, i, xff=None):
    headers = {"X-Forwarded-For": xff} if xff else {}
    return client.post(
        "/links", json={"url": f"https://example.com/{i}"}, headers=headers
    )


def test_exceeding_the_creation_limit_returns_429_with_retry_after_and_writes_no_row(
    make_client,
):
    client = make_client(
        LINKS_RATE_LIMIT_MAX="3",
        LINKS_RATE_LIMIT_WINDOW_SECONDS="60",
        LINKS_TRUST_PROXY_HEADER="true",
    )
    caller = "203.0.113.10"

    for i in range(3):
        resp = _create(client, i, caller)
        assert resp.status_code == 201, f"request {i} under the limit: {resp.text}"
    assert client.db.count() == 3

    over = _create(client, 99, caller)

    assert over.status_code == 429, f"expected 429, got {over.status_code}: {over.text}"
    retry_after = over.headers.get("retry-after")
    assert retry_after is not None, f"no Retry-After header: {dict(over.headers)!r}"
    assert retry_after.strip().isdigit(), f"Retry-After not numeric: {retry_after!r}"
    assert 1 <= int(retry_after) <= 60
    assert client.db.count() == 3, (
        f"the throttled request still wrote a row: {client.db.rows()!r}"
    )


def test_the_limit_is_per_client_key_so_another_ip_still_succeeds(make_client):
    client = make_client(
        LINKS_RATE_LIMIT_MAX="3",
        LINKS_RATE_LIMIT_WINDOW_SECONDS="60",
        LINKS_TRUST_PROXY_HEADER="true",
    )
    throttled = "203.0.113.10"
    other = "198.51.100.7"

    for i in range(3):
        assert _create(client, i, throttled).status_code == 201
    assert _create(client, 99, throttled).status_code == 429

    fresh = _create(client, 100, other)

    assert fresh.status_code == 201, (
        f"a different client key was throttled by another key's usage: {fresh.text}"
    )
    assert client.db.count() == 4


def test_the_limited_key_is_the_last_x_forwarded_for_entry_when_the_proxy_is_trusted(
    make_client,
):
    client = make_client(
        LINKS_RATE_LIMIT_MAX="2",
        LINKS_RATE_LIMIT_WINDOW_SECONDS="60",
        LINKS_TRUST_PROXY_HEADER="true",
    )
    real_peer = "203.0.113.10"

    for i in range(2):
        assert _create(client, i, real_peer).status_code == 201

    spoofed_prefix = _create(client, 3, f"1.2.3.4, {real_peer}")

    assert spoofed_prefix.status_code == 429, (
        "prepending an X-Forwarded-For entry evaded the limit; the key must be "
        f"the last entry. Got {spoofed_prefix.status_code}: {spoofed_prefix.text}"
    )
    assert client.db.count() == 2


def test_x_forwarded_for_is_ignored_when_the_proxy_header_is_not_trusted(make_client):
    client = make_client(
        LINKS_RATE_LIMIT_MAX="2",
        LINKS_RATE_LIMIT_WINDOW_SECONDS="60",
        LINKS_TRUST_PROXY_HEADER="false",
    )

    assert _create(client, 0, "203.0.113.1").status_code == 201
    assert _create(client, 1, "203.0.113.2").status_code == 201
    third = _create(client, 2, "203.0.113.3")

    assert third.status_code == 429, (
        "with LINKS_TRUST_PROXY_HEADER=false the socket peer is the key, so a "
        f"rotating X-Forwarded-For must not reset the counter; got {third.status_code}"
    )
    assert client.db.count() == 2


def test_requests_below_the_limit_are_unaffected(make_client):
    client = make_client(LINKS_RATE_LIMIT_MAX="5")

    statuses = [_create(client, i).status_code for i in range(5)]

    assert statuses == [201] * 5, statuses
    assert client.db.count() == 5
"},{"path":"tests/test_code_collision.py","content":""""Code generation: collisions retry, exhaustion is bounded, codes are unique."""
from __future__ import annotations

from conftest import patch_code_generator
from helpers import BASE62, extract_code


def test_a_colliding_generated_code_is_retried_and_a_unique_code_is_returned(
    client, monkeypatch
):
    first = client.post("/links", json={"url": "https://example.com/first"})
    assert first.status_code == 201, first.text
    taken = extract_code(first.json())

    state = {"calls": 0}

    def factory(original):
        def fake(*args, **kwargs):
            state["calls"] += 1
            if state["calls"] > 25:
                raise AssertionError(
                    "code generator called unboundedly; the retry loop does not "
                    "terminate"
                )
            if state["calls"] == 1:
                return taken
            return original(*args, **kwargs)

        return fake

    patch_code_generator(monkeypatch, client.app_module, factory)

    second = client.post("/links", json={"url": "https://example.com/second"})

    assert second.status_code == 201, (
        f"a single collision must be retried, not surfaced: {second.status_code} "
        f"{second.text}"
    )
    new_code = extract_code(second.json())
    assert new_code != taken, "the service returned an already-issued code"
    assert len(new_code) == 7 and set(new_code) <= BASE62
    assert state["calls"] >= 2, "the generator was not retried after the collision"

    rows = client.db.rows()
    assert len(rows) == 2, rows
    assert {r["code"] for r in rows} == {taken, new_code}
    assert {r["destination"] for r in rows} == {
        "https://example.com/first",
        "https://example.com/second",
    }


def test_unbroken_collisions_fail_bounded_with_503_rather_than_500_or_a_hang(
    client, monkeypatch
):
    first = client.post("/links", json={"url": "https://example.com/first"})
    assert first.status_code == 201, first.text
    taken = extract_code(first.json())

    state = {"calls": 0}

    def factory(original):
        def fake(*args, **kwargs):
            state["calls"] += 1
            if state["calls"] > 50:
                raise AssertionError(
                    "code generator retried without bound; LINKS_CODE_MAX_ATTEMPTS "
                    "is not enforced"
                )
            return taken

        return fake

    patch_code_generator(monkeypatch, client.app_module, factory)

    resp = client.post("/links", json={"url": "https://example.com/second"})

    assert resp.status_code == 503, (
        f"exhausted collision retries must yield 503, got {resp.status_code}: "
        f"{resp.text}"
    )
    assert state["calls"] <= 6, (
        "LINKS_CODE_MAX_ATTEMPTS=5 was exceeded: "
        f"{state['calls']} generator calls"
    )
    rows = client.db.rows()
    assert len(rows) == 1, f"a duplicate row was written: {rows!r}"
    assert rows[0]["code"] == taken


def test_one_thousand_generated_codes_contain_no_duplicates(client, monkeypatch):
    captured = []

    def factory(original):
        def spy(*args, **kwargs):
            value = original(*args, **kwargs)
            captured.append(value)
            return value

        return spy

    original = patch_code_generator(monkeypatch, client.app_module, factory)

    codes = [original() for _ in range(1000)]

    assert len(set(codes)) == 1000, (
        f"generated codes collided: {1000 - len(set(codes))} duplicates"
    )
    assert all(len(c) == 7 for c in codes), "code length is not LINKS_CODE_LENGTH=7"
    assert all(set(c) <= BASE62 for c in codes), "codes are not base62"


def test_forty_creations_over_http_all_yield_distinct_codes(make_client):
    client = make_client(LINKS_RATE_LIMIT_MAX="1000")

    codes = []
    for i in range(40):
        resp = client.post("/links", json={"url": f"https://example.com/{i}"})
        assert resp.status_code == 201, resp.text
        codes.append(extract_code(resp.json()))

    assert len(set(codes)) == 40, f"duplicate codes issued: {codes}"
    assert client.db.count() == 40
