from __future__ import annotations

from helpers import extract_code

PAST = "2001-01-01T00:00:00Z"


def _click_count(client, code):
    row = client.db.row_for(code)
    assert row is not None, f"no row for code {code!r}"
    assert "click_count" in row, f"links row has no click_count column: {row!r}"
    return row["click_count"]


def test_a_successful_redirect_increments_the_click_count_exactly_once(client):
    code = extract_code(
        client.post("/links", json={"url": "https://example.com/a"}).json()
    )
    assert _click_count(client, code) == 0

    resp = client.get(f"/{code}", follow_redirects=False)

    assert resp.status_code == 302
    assert _click_count(client, code) == 1, (
        "one successful redirect must record exactly one click"
    )
    assert client.db.row_for(code)["last_clicked_at"], (
        "last_clicked_at was not set after the first successful redirect"
    )


def test_three_successful_redirects_record_three_clicks(client):
    code = extract_code(
        client.post("/links", json={"url": "https://example.com/a"}).json()
    )

    for _ in range(3):
        assert client.get(f"/{code}", follow_redirects=False).status_code == 302

    assert _click_count(client, code) == 3


def test_an_expired_link_does_not_increment_the_click_count(client):
    code = extract_code(
        client.post("/links", json={"url": "https://example.com/a"}).json()
    )
    client.db.set_expires_at(code, PAST)

    resp = client.get(f"/{code}", follow_redirects=False)

    assert resp.status_code == 410
    assert _click_count(client, code) == 0, (
        "a failed (expired) redirect must not be counted as a click"
    )
    assert client.db.row_for(code)["last_clicked_at"] in (None, ""), (
        "last_clicked_at was written for a redirect that never happened"
    )


def test_a_rebound_destination_rejected_at_redirect_time_is_not_counted(
    client, dns_map
):
    code = extract_code(
        client.post("/links", json={"url": "http://rebind.example.com/x"}).json()
    )
    dns_map["rebind.example.com"] = ["169.254.169.254"]

    resp = client.get(f"/{code}", follow_redirects=False)

    assert resp.status_code in (502, 410), resp.status_code
    assert _click_count(client, code) == 0, (
        "a redirect refused at resolution time must not be counted as a click"
    )


def test_a_lookup_for_an_unknown_code_counts_nothing_anywhere(client):
    code = extract_code(
        client.post("/links", json={"url": "https://example.com/a"}).json()
    )

    assert client.get("/Qq1Ww2E", follow_redirects=False).status_code == 404

    assert _click_count(client, code) == 0
    assert client.db.count() == 1
"}],"coverage_notes":"tests/test_round_trip.py covers the create->follow round trip (201, code shape/base62/length 7, short_url built from LINKS_PUBLIC_BASE_URL, exactly one persisted row, exact 302 + Location + Cache-Control: no-store), unauthenticated creation, non-sequential codes, and non-exposure of the internal row id. tests/test_scheme_rejection.py covers javascript:/data:/file: (400, scheme-flavoured machine error, and DB row count asserted to be 0, not just the status) plus ftp/mailto/blob/vbscript/about/gopher, and proves the datastore is still usable afterwards. tests/test_private_destinations.py covers 169.254.169.254, 127.0.0.1 (asserting error code destination_not_routable), 127.1.2.3, [::1], 10/8, 172.16/12, 192.168/16, 100.64/10, 0/8, 224/4, fc00::/7, fe80::/10, hostnames that DNS-resolve into private/link-local space (metadata.google.internal, internal.corp.example.com, nat64.example.net), the zero-outbound-connection requirement, and DNS re-validation at redirect time. tests/test_url_validation.py covers credentials_in_url, the 2048/2049 length boundary in both directions, malformed URLs, punycode normalisation of a Cyrillic homograph host (expected A-label computed at runtime rather than hardcoded), and the JSON-only/no-markup-echo rule. tests/test_expiry.py controls time by writing a past expires_at directly into the fixture database (no sleeps anywhere in the suite): 410 with no Location, 410 distinguishable from 404, no destination leak in the 410 body, default 30-day and explicit 1-day offsets, and rejection of 0/-1/366/100000 and non-numeric expiries with no row written. tests/test_rate_limit.py drives past LINKS_RATE_LIMIT_MAX (set to 3 via the exact env name), asserts 429 + numeric Retry-After within the window + no row written, then shows a different key still gets 201; it also pins that the key is the LAST X-Forwarded-For entry when LINKS_TRUST_PROXY_HEADER=true and that XFF is ignored when it is false. tests/test_code_collision.py forces the generator to return an already-issued code once (asserting retry, a distinct code, 201 and two distinct rows), then forces permanent collision (asserting bounded attempts and 503 code_generation_failed rather than 500 or a hang), plus 1000 direct generator calls with no duplicates and 40 HTTP creations with distinct codes. tests/test_unknown_code.py covers 404 with no Location and no row created, out-of-alphabet codes, datastore health afterwards, and no markup reflection. tests/test_click_analytics.py asserts one increment per successful redirect, three for three, and zero for expired, rebound-rejected and unknown-code requests.

Deliberate non-coverage and risks worth flagging: (1) The design names no Python module, so tests/conftest.py probes a list of conventional entrypoints (app.main, app, main, src.main, ...) and fails loudly if none exposes an ASGI app -- a naming mismatch will read as an import failure, not a silent skip. (2) The collision tests locate the code generator by introspecting module-level functions whose names mention 'code' plus a generation verb; if the implementation hides generation inside a class method or a closure, those three tests fail with an explicit message rather than being skipped, which should be triaged as a discoverability finding rather than a behavioural bug. (3) The network is stubbed at socket.getaddrinfo/gethostbyname (which also covers asyncio's default loop.getaddrinfo); an implementation resolving via dnspython or a c-ares binding would bypass the stub and reach the real resolver -- that is itself a finding, since the suite must run offline. All outbound socket connects are hard-blocked. (4) Non-numeric expires_in_days is accepted as 400 or 422 because FastAPI/pydantic returns 422 for a type error by default while the acceptance criteria say 400; the row-count assertion is strict either way, and a 422 here is a design/implementation mismatch worth recording. (5) Click-count assertions read the database immediately after the redirect response; the design puts the increment on a background task, which Starlette completes before TestClient returns. A fire-and-forget asyncio.create_task implementation would make these tests red -- that is intentional, since such an implementation loses counts under normal operation too. (6) Not covered: persistence across process restart, the periodic expiry purge, TLS/proxy termination, LINKS_ALLOW_PRIVATE_DESTINATIONS=true, LINKS_DNS_CACHE_TTL_SECONDS>0, LINKS_DNS_TIMEOUT_MS behaviour on a hanging resolver, and log output (assertions are on status codes, headers, response bodies and database rows only)."}

