"""Shared assertion helpers.

Kept deliberately small: every helper either extracts a value from an HTTP
response or normalises it. No helper performs I/O.
"""
from __future__ import annotations

import json
import string
from datetime import datetime

BASE62 = set(string.ascii_letters + string.digits)


def response_blob(resp) -> str:
    """Lower-cased serialisation of the response body, JSON or raw."""
    try:
        return json.dumps(resp.json()).lower()
    except ValueError:
        return resp.text.lower()


def error_code(resp) -> str:
    """Best-effort extraction of the machine-readable error code."""
    try:
        body = resp.json()
    except ValueError:
        return ""
    if not isinstance(body, dict):
        return ""
    for key in ("error", "error_code", "code", "detail", "message", "reason"):
        value = body.get(key)
        if isinstance(value, str):
            return value.lower()
        if isinstance(value, dict):
            for inner in ("error", "error_code", "code", "message", "msg"):
                if isinstance(value.get(inner), str):
                    return value[inner].lower()
        if isinstance(value, list) and value and isinstance(value[0], dict):
            for inner in ("error", "error_code", "code", "msg", "message", "type"):
                if isinstance(value[0].get(inner), str):
                    return value[0][inner].lower()
    return ""


def has_error_token(resp, token: str) -> bool:
    return token.lower() in (error_code(resp) + " " + response_blob(resp))


def extract_code(body: dict):
    for key in ("code", "short_code", "shortcode", "slug", "key"):
        value = body.get(key)
        if isinstance(value, str):
            return value
    short_url = body.get("short_url") or body.get("shortUrl") or ""
    if short_url:
        return short_url.rstrip("/").rsplit("/", 1)[-1]
    return None


def parse_iso(value: str) -> datetime:
    assert isinstance(value, str), f"expected an ISO-8601 string, got {value!r}"
    return datetime.fromisoformat(value.replace("Z", "+00:00"))

"""Fixtures: fresh database per test, stubbed resolver, no network at all.

The implementation is imported fresh for every test so that it re-reads the
environment variables named in the design.  Nothing is shared between tests:
each client gets its own SQLite file under the test's tmp_path.
"""
from __future__ import annotations

import importlib
import inspect
import ipaddress
import os
import socket
import sqlite3
import sys

import pytest
from fastapi.testclient import TestClient

PUBLIC_IP = "93.184.216.34"
PUBLIC_IP6 = "2606:2800:220:1:248:1893:25c8:1946"

APP_MODULE_CANDIDATES = (
    "app.main",
    "app",
    "main",
    "src.main",
    "src.app",
    "api.main",
    "links.main",
    "links",
    "links_service.main",
    "shortener.main",
    "shortener",
    "service.main",
    "server",
    "src.server",
    "url_shortener.main",
    "urlshortener.main",
)

APP_ROOTS = {name.split(".")[0] for name in APP_MODULE_CANDIDATES} | {
    "config",
    "settings",
    "database",
    "db",
    "models",
    "storage",
    "validation",
    "validators",
    "ratelimit",
    "rate_limit",
    "codes",
    "shortcode",
}

# Exactly the names and defaults from the design's configuration list.
DEFAULT_ENV = {
    "LINKS_BIND_HOST": "127.0.0.1",
    "LINKS_BIND_PORT": "8080",
    "LINKS_PUBLIC_BASE_URL": "https://short.example.com",
    "LINKS_DEFAULT_EXPIRY_DAYS": "30",
    "LINKS_MAX_EXPIRY_DAYS": "365",
    "LINKS_MAX_URL_LENGTH": "2048",
    "LINKS_CODE_LENGTH": "7",
    "LINKS_CODE_MAX_ATTEMPTS": "5",
    "LINKS_RATE_LIMIT_MAX": "20",
    "LINKS_RATE_LIMIT_WINDOW_SECONDS": "60",
    "LINKS_TRUST_PROXY_HEADER": "false",
    "LINKS_DNS_TIMEOUT_MS": "2000",
    "LINKS_DNS_CACHE_TTL_SECONDS": "0",
    "LINKS_ALLOW_PRIVATE_DESTINATIONS": "false",
    "LINKS_LOG_LEVEL": "info",
}


def _purge_app_modules() -> None:
    for name in list(sys.modules):
        if name.split(".")[0] in APP_ROOTS:
            sys.modules.pop(name, None)


def load_app():
    """Import the service fresh and return (module, asgi_app)."""
    _purge_app_modules()
    problems = []
    for name in APP_MODULE_CANDIDATES:
        try:
            module = importlib.import_module(name)
        except ModuleNotFoundError as exc:
            problems.append(f"{name}: {exc}")
            continue
        except Exception as exc:  # an import-time explosion is a real defect
            problems.append(f"{name}: {type(exc).__name__}: {exc}")
            continue
        app = getattr(module, "app", None)
        if app is None:
            for factory in ("create_app", "get_app", "build_app", "make_app"):
                fn = getattr(module, factory, None)
                if callable(fn):
                    try:
                        app = fn()
                    except Exception as exc:
                        problems.append(f"{name}.{factory}(): {exc}")
                        app = None
                    break
        if app is not None and hasattr(app, "router"):
            return module, app
        problems.append(f"{name}: imported but exposes no ASGI application")
    pytest.fail(
        "Could not import the FastAPI application. Tried: " + " | ".join(problems)
    )


class DB:
    """Direct read access to the SQLite file named by LINKS_DB_PATH."""

    def __init__(self, path: str):
        self.path = path

    def _connect(self):
        con = sqlite3.connect(self.path, timeout=5)
        con.row_factory = sqlite3.Row
        return con

    def rows(self, table: str = "links"):
        if not os.path.exists(self.path):
            return []
        try:
            con = self._connect()
        except sqlite3.Error:
            return []
        try:
            return [dict(r) for r in con.execute(f"SELECT * FROM {table}")]
        except sqlite3.OperationalError:
            return []
        finally:
            con.close()

    def count(self, table: str = "links") -> int:
        return len(self.rows(table))

    def row_for(self, code: str):
        for row in self.rows():
            if row.get("code") == code:
                return row
        return None

    def execute(self, sql: str, params=()):
        con = self._connect()
        try:
            con.execute(sql, params)
            con.commit()
        finally:
            con.close()

    def set_expires_at(self, code: str, value: str):
        self.execute("UPDATE links SET expires_at = ? WHERE code = ?", (value, code))


@pytest.fixture
def outbound_connections():
    """Every socket connect attempt made during the test lands here."""
    return []


@pytest.fixture
def dns_map():
    """Mutable hostname -> [ip] map consulted by the stubbed resolver."""
    return {
        "example.com": [PUBLIC_IP],
        "www.example.com": [PUBLIC_IP],
        "evil.example.com": [PUBLIC_IP],
        "short.example.com": [PUBLIC_IP],
        "metadata.google.internal": ["169.254.169.254"],
        "internal.corp.example.com": ["10.0.0.5"],
        "nat64.example.net": ["100.64.0.9"],
        "rebind.example.com": [PUBLIC_IP],
        "v6only.example.com": [PUBLIC_IP6],
    }


NXDOMAIN_HOSTS = {"nonexistent.invalid", "does-not-resolve.example"}


def _normalise_host(host):
    if not isinstance(host, str):
        return ""
    host = host.strip().strip("[]").rstrip(".").lower()
    try:
        host.encode("ascii")
    except UnicodeEncodeError:
        try:
            host = host.encode("idna").decode("ascii")
        except Exception:
            pass
    return host


@pytest.fixture(autouse=True)
def stub_network(monkeypatch, dns_map, outbound_connections):
    """No real DNS, no real sockets. Deterministic, offline, per test."""

    def addresses_for(host):
        key = _normalise_host(host)
        if key in NXDOMAIN_HOSTS:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        try:
            return [str(ipaddress.ip_address(key))]
        except ValueError:
            pass
        if key in dns_map:
            return list(dns_map[key])
        if not key:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        # Unmapped hosts are treated as ordinary public destinations so that
        # tests never depend on the machine's real resolver.
        return [PUBLIC_IP]

    def fake_getaddrinfo(host, port, family=0, type=0, proto=0, flags=0):
        results = []
        portnum = port if isinstance(port, int) else 0
        for addr in addresses_for(host):
            ip = ipaddress.ip_address(addr)
            if ip.version == 4:
                if family in (0, socket.AF_INET, socket.AF_UNSPEC):
                    results.append(
                        (socket.AF_INET, socket.SOCK_STREAM, 6, "", (str(ip), portnum))
                    )
            else:
                if family in (0, socket.AF_INET6, socket.AF_UNSPEC):
                    results.append(
                        (
                            socket.AF_INET6,
                            socket.SOCK_STREAM,
                            6,
                            "",
                            (str(ip), portnum, 0, 0),
                        )
                    )
        if not results:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        return results

    def fake_gethostbyname(host):
        for addr in addresses_for(host):
            if ipaddress.ip_address(addr).version == 4:
                return addr
        raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")

    def fake_gethostbyname_ex(host):
        v4 = [a for a in addresses_for(host) if ipaddress.ip_address(a).version == 4]
        if not v4:
            raise socket.gaierror(socket.EAI_NONAME, "Name or service not known")
        return (_normalise_host(host), [], v4)

    monkeypatch.setattr(socket, "getaddrinfo", fake_getaddrinfo)
    monkeypatch.setattr(socket, "gethostbyname", fake_gethostbyname)
    monkeypatch.setattr(socket, "gethostbyname_ex", fake_gethostbyname_ex)

    def blocked_connect(self, address, *args, **kwargs):
        outbound_connections.append(address)
        raise AssertionError(f"outbound connection attempted to {address!r}")

    def blocked_create_connection(address, *args, **kwargs):
        outbound_connections.append(address)
        raise AssertionError(f"outbound connection attempted to {address!r}")

    monkeypatch.setattr(socket.socket, "connect", blocked_connect)
    monkeypatch.setattr(socket.socket, "connect_ex", blocked_connect)
    monkeypatch.setattr(socket, "create_connection", blocked_create_connection)
    yield


@pytest.fixture
def make_client(monkeypatch, tmp_path):
    """Factory: make_client(LINKS_RATE_LIMIT_MAX='3') -> TestClient.

    Each client gets its own database file, its own freshly imported module
    graph, and the design's configuration defaults unless overridden.
    """
    opened = []

    def _make(**overrides):
        db_path = str(tmp_path / f"links-{len(opened)}.db")
        for key in list(os.environ):
            if key.startswith("LINKS_"):
                monkeypatch.delenv(key, raising=False)
        env = dict(DEFAULT_ENV)
        env["LINKS_DB_PATH"] = db_path
        env.update({k: str(v) for k, v in overrides.items()})
        for key, value in env.items():
            monkeypatch.setenv(key, value)
        module, app = load_app()
        manager = TestClient(app)
        client = manager.__enter__()
        opened.append(manager)
        client.app_module = module
        client.db = DB(db_path)
        client.db_path = db_path
        return client

    yield _make

    for manager in reversed(opened):
        try:
            manager.__exit__(None, None, None)
        except Exception:
            pass
    _purge_app_modules()


@pytest.fixture
def client(make_client):
    return make_client()


def find_code_generators(app_module):
    """Locate the short-code generator function inside the app's modules."""
    roots = {app_module.__name__.split(".")[0]}
    found = []
    for mod_name, mod in list(sys.modules.items()):
        if mod is None or mod_name.split(".")[0] not in roots:
            continue
        for attr in dir(mod):
            try:
                obj = getattr(mod, attr)
            except Exception:
                continue
            if not inspect.isfunction(obj):
                continue
            lowered = attr.lower()
            if "code" not in lowered:
                continue
            if not any(w in lowered for w in ("gen", "make", "new", "rand", "mint", "create")):
                continue
            try:
                sig = inspect.signature(obj)
            except (TypeError, ValueError):
                continue
            required = [
                p
                for p in sig.parameters.values()
                if p.default is p.empty
                and p.kind
                in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD, p.KEYWORD_ONLY)
            ]
            if len(required) > 1:
                continue
            found.append((mod, attr, obj))
    return found


def patch_code_generator(monkeypatch, app_module, side_effect_factory):
    """Replace the code generator everywhere it is bound.

    side_effect_factory receives the original function and returns the
    replacement.  Returns the original callable.
    """
    found = find_code_generators(app_module)
    if not found:
        pytest.fail(
            "No short-code generator function found in the application modules; "
            "collision retry cannot be exercised. Expected a module-level "
            "function whose name mentions 'code' and generation "
            "(e.g. generate_code)."
        )
    original = found[0][2]
    replacement = side_effect_factory(original)
    for mod, attr, obj in found:
        if obj is original:
            monkeypatch.setattr(mod, attr, replacement)
    return original

"""Expiry arithmetic and the behaviour of a lapsed link. No sleeping."""
from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from helpers import extract_code, has_error_token, parse_iso

PAST = "2001-01-01T00:00:00Z"


def test_default_expiry_is_thirty_days_after_creation(client):
    before = datetime.now(timezone.utc)
    resp = client.post("/links", json={"url": "https://example.com/a"})
    after = datetime.now(timezone.utc)

    assert resp.status_code == 201, resp.text
    expires_at = resp.json()["expires_at"]
    assert expires_at.endswith("Z"), f"expires_at is not UTC 'Z' form: {expires_at!r}"
    parsed = parse_iso(expires_at)
    assert before + timedelta(days=30) - timedelta(seconds=60) <= parsed
    assert parsed <= after + timedelta(days=30) + timedelta(seconds=60)


def test_expires_in_days_of_one_yields_an_expiry_one_day_out(client):
    before = datetime.now(timezone.utc)
    resp = client.post(
        "/links", json={"url": "https://example.com/a", "expires_in_days": 1}
    )
    after = datetime.now(timezone.utc)

    assert resp.status_code == 201, resp.text
    parsed = parse_iso(resp.json()["expires_at"])
    assert before + timedelta(days=1) - timedelta(seconds=60) <= parsed
    assert parsed <= after + timedelta(days=1) + timedelta(seconds=60)
