"},{"path":"tests/test_rate_limit.py","content":""""The creation rate limit is enforced in-process and keyed per client."""

KEY_A = "198.51.100.7"
KEY_B = "198.51.100.8"
RATE_ERRORS = {"rate_limited", "rate_limit_exceeded", "too_many_requests"}


def test_requests_past_the_window_limit_return_429_with_retry_after_and_write_no_row(
    make_client, create_link, db, helpers
):
    client = make_client(LINKS_RATE_LIMIT_MAX=3, LINKS_RATE_LIMIT_WINDOW_SECONDS=60,
                         LINKS_TRUST_PROXY_HEADER="true")
    headers = {"X-Forwarded-For": KEY_A}

    for i in range(3):
        resp = create_link(client, f"https://example.com/a{i}", headers=headers)
        assert resp.status_code == 201, f"request {i + 1} of 3 under the limit failed: {resp.text}"
    assert db.count() == 3

    blocked = create_link(client, "https://example.com/over", headers=headers)

    assert blocked.status_code == 429, (
        f"4th request with LINKS_RATE_LIMIT_MAX=3 returned {blocked.status_code}: {blocked.text}"
    )
    retry_after = blocked.headers.get("retry-after")
    assert retry_after is not None, f"429 carried no Retry-After: {dict(blocked.headers)}"
    assert retry_after.strip().isdigit(), f"Retry-After is not an integer: {retry_after!r}"
    assert 1 <= int(retry_after) <= 60, f"Retry-After {retry_after} outside the 60s window"
    assert helpers.error_code(blocked) in RATE_ERRORS, blocked.text
    assert db.count() == 3, "the throttled request still wrote a row"


def test_the_limit_is_per_client_key_so_a_different_key_still_creates(
    make_client, create_link, db, helpers
):
    client = make_client(LINKS_RATE_LIMIT_MAX=3, LINKS_RATE_LIMIT_WINDOW_SECONDS=60,
                         LINKS_TRUST_PROXY_HEADER="true")

    for i in range(3):
        assert create_link(
            client, f"https://example.com/a{i}", headers={"X-Forwarded-For": KEY_A}
        ).status_code == 201
    assert create_link(
        client, "https://example.com/over", headers={"X-Forwarded-For": KEY_A}
    ).status_code == 429

    other = create_link(client, "https://example.com/b", headers={"X-Forwarded-For": KEY_B})

    assert other.status_code == 201, (
        f"a second client key was throttled by the first key's bucket: "
        f"{other.status_code} {other.text}"
    )
    assert helpers.code_of(other.json())
    assert db.count() == 4

    # and the exhausted key is still blocked afterwards
    again = create_link(client, "https://example.com/still-over", headers={"X-Forwarded-For": KEY_A})
    assert again.status_code == 429, again.text
    assert db.count() == 4


def test_redirects_are_not_rate_limited(make_client, create_link, helpers):
    client = make_client(LINKS_RATE_LIMIT_MAX=2, LINKS_RATE_LIMIT_WINDOW_SECONDS=60,
                         LINKS_TRUST_PROXY_HEADER="true")
    headers = {"X-Forwarded-For": KEY_A}
    code = helpers.code_of(create_link(client, "https://example.com/a", headers=headers).json())

    for _ in range(10):
        resp = client.get(f"/{code}", headers=headers, follow_redirects=False)
        assert resp.status_code == 302, f"a shared link was throttled: {resp.status_code}"
"},{"path":"tests/test_code_collision.py","content":""""A generated code that already exists must be retried, not surfaced as an error."""

import random
import secrets

NOVEL_CODE = "Zq7Wm3x"  # 7 base62 characters, matching LINKS_CODE_LENGTH=7


def _run_rng_fallback(make_client, create_link, link_db, helpers, monkeypatch, tmp_path):
    """No named generator seam: drive the RNG so code #2's first attempt collides."""
    scripted = helpers.ScriptedRandom(code_len=7)
    for module in (secrets, random):
        monkeypatch.setattr(module, "choice", scripted.choice, raising=False)
    monkeypatch.setattr(secrets, "randbelow", scripted.randbelow, raising=False)
    monkeypatch.setattr(secrets, "token_bytes", scripted.token_bytes, raising=False)
    monkeypatch.setattr(secrets, "token_hex", scripted.token_hex, raising=False)
    monkeypatch.setattr(secrets, "token_urlsafe", scripted.token_urlsafe, raising=False)

    db_path = tmp_path / "collision.db"
    client = make_client(LINKS_DB_PATH=str(db_path))
    db = link_db(str(db_path))

    first = create_link(client, "https://example.com/one")
    assert first.status_code == 201, first.text
    second = create_link(client, "https://example.com/two")

    assert scripted.calls > 0, (
        "no code-generation seam was found: expose a generate_code()-style function or "
        "derive codes from secrets.choice/randbelow/token_* so a collision can be forced"
    )
    assert second.status_code == 201, (
        f"a colliding code produced {second.status_code} instead of a retry: {second.text}"
    )
    code1 = helpers.code_of(first.json())
    code2 = helpers.code_of(second.json())
    assert code1 and code2
    assert code1 != code2, "the service returned an already-issued code"
    assert db.count() == 2
    assert {r["code"] for r in db.rows()} == {code1, code2}


def test_a_colliding_generated_code_is_retried_and_a_unique_code_is_returned(
    client, make_client, create_link, db, link_db, helpers, monkeypatch, tmp_path
):
    first = create_link(client, "https://example.com/one")
    assert first.status_code == 201, first.text
    existing = helpers.code_of(first.json())

    targets = helpers.find_code_generators()
    if not targets:
        _run_rng_fallback(make_client, create_link, link_db, helpers, monkeypatch, tmp_path)
        return

    state = {"n": 0}

    def _make_fake(orig):
        def _fake(*args, **kwargs):
            state["n"] += 1
            if state["n"] == 1:
                return existing
            if state["n"] == 2:
                return NOVEL_CODE
            return orig(*args, **kwargs)

        return _fake

    for module, attr in targets:
        monkeypatch.setattr(module, attr, _make_fake(getattr(module, attr)))

    second = create_link(client, "https://example.com/two")

    if state["n"] == 0:
        # the discovered name was never called; fall back to driving the RNG
        monkeypatch.undo()
        _run_rng_fallback(make_client, create_link, link_db, helpers, monkeypatch, tmp_path)
        return

    assert second.status_code == 201, (
        f"a forced code collision produced {second.status_code} instead of a retry: {second.text}"
    )
    assert state["n"] >= 2, "the service did not retry after the UNIQUE collision"
    assert helpers.code_of(second.json()) == NOVEL_CODE
    assert db.count() == 2, f"expected both links persisted, got {db.rows()}"
    assert {r["code"] for r in db.rows()} == {existing, NOVEL_CODE}

    for code in (existing, NOVEL_CODE):
        redirect = client.get(f"/{code}", follow_redirects=False)
        assert redirect.status_code == 302, f"{code} did not resolve: {redirect.status_code}"
