"},{"path":"tests/test_click_analytics.py","content":""""Click counters move exactly once per successful redirect and never on failures."""

PAST = "2000-01-01T00:00:00Z"


def _pump(client):
    return lambda: client.get("/0000000", follow_redirects=False)


def test_a_successful_redirect_increments_the_click_count_exactly_once(
    client, create_link, db, helpers
):
    code = helpers.code_of(create_link(client, "https://example.com/a").json())
    assert db.click_count_of(code) == 0, "a brand new link should start at zero clicks"

    resp = client.get(f"/{code}", follow_redirects=False)
    assert resp.status_code == 302, resp.text

    count = helpers.wait_until(lambda: db.click_count_of(code) or 0, _pump(client))
    assert count == 1, f"expected exactly one click after one redirect, got {count!r}"

    row = db.row_for(code)
    last = next((row[k] for k in ("last_clicked_at", "last_click_at") if k in row), "")
    assert last, "last_clicked_at was not stamped after a successful redirect"


def test_two_successful_redirects_increment_the_click_count_twice(
    client, create_link, db, helpers
):
    code = helpers.code_of(create_link(client, "https://example.com/a").json())

    assert client.get(f"/{code}", follow_redirects=False).status_code == 302
    helpers.wait_until(lambda: (db.click_count_of(code) or 0) >= 1, _pump(client))
    assert client.get(f"/{code}", follow_redirects=False).status_code == 302
    count = helpers.wait_until(lambda: (db.click_count_of(code) or 0) >= 2, _pump(client))

    assert db.click_count_of(code) == 2, f"expected 2 clicks, got {db.click_count_of(code)!r}"
    assert count


def test_an_expired_redirect_does_not_increment_the_click_count(client, create_link, db, helpers):
    live = helpers.code_of(create_link(client, "https://example.com/live").json())
    dead = helpers.code_of(create_link(client, "https://example.com/dead").json())
    db.set_expiry(dead, PAST)

    assert client.get(f"/{live}", follow_redirects=False).status_code == 302
    helpers.wait_until(lambda: (db.click_count_of(live) or 0) >= 1, _pump(client))

    expired = client.get(f"/{dead}", follow_redirects=False)
    assert expired.status_code == 410, expired.text
    helpers.wait_until(lambda: False, _pump(client), tries=5)

    assert db.click_count_of(dead) == 0, (
        f"a 410 redirect attempt counted as a click: {db.click_count_of(dead)!r}"
    )
    assert db.click_count_of(live) == 1, "the unrelated live link's counter drifted"


def test_a_404_lookup_does_not_touch_any_click_counter(client, create_link, db, helpers):
    code = helpers.code_of(create_link(client, "https://example.com/a").json())

    assert client.get("/aB3xyz9", follow_redirects=False).status_code == 404
    helpers.wait_until(lambda: False, _pump(client), tries=5)

    assert db.click_count_of(code) == 0
    assert db.count() == 1
"}],"coverage_notes":"tests/conftest.py: fresh tmp SQLite file + freshly imported app module per test (project modules are purged from sys.modules so env is re-read), env bound verbatim to the design's LINKS_* names and defaults, DNS stubbed offline at import (socket.getaddrinfo/gethostbyname), and an autouse guard that turns any outbound socket connect into a failure. It also probes once per session whether the create body field is 'destination_url' (README) or 'url' (acceptance criteria) and adapts, and discovers the app module by convention (override with LINKS_APP_MODULE).

Coverage by required item: round trip -> tests/test_round_trip.py (201, exact short_url built from LINKS_PUBLIC_BASE_URL, one persisted row with the submitted destination, GET returns exactly 302 with Location equal to the stored destination; Cache-Control: no-store is a separate test so a missing header does not mask the redirect assertion). Open redirect -> tests/test_scheme_rejection.py (javascript:, data:, file: plus ftp/mailto/blob/vbscript/about, each asserting 400, a machine-readable error code, and db.count()==0 read back from SQLite; also credentials_in_url, malformed and >2048 URLs, and that error bodies are JSON and do not echo markup). Private/link-local -> tests/test_private_destinations.py (169.254.169.254, 127.0.0.1, [::1], 10/8, 172.16/12, 192.168/16, 100.64/10, 0.0.0.0/8, 224/4, fc00::/7, fe80::/10, plus hostnames resolving into those ranges including metadata.google.internal, each asserting row absence and zero outbound connections; includes a rebinding re-validation test at redirect time). Expired -> tests/test_expiry.py (expiry written into the row as a past ISO timestamp; no sleeps anywhere; 410, no Location, no destination leak, row survives; plus default-30-day and 1-day arithmetic and out-of-range expiry rejection). Rate limit -> tests/test_rate_limit.py (LINKS_RATE_LIMIT_MAX=3 with LINKS_TRUST_PROXY_HEADER=true, 4th request 429 with an integer Retry-After in [1,60] and no extra row, then a different X-Forwarded-For key still gets 201 and the exhausted key stays blocked; redirects proven unthrottled). Collision -> tests/test_code_collision.py (patches a discovered generate_code-style callable to return an existing code first and a novel code second, asserting 201, the novel code, >=2 generator calls and two rows; if no named seam exists it falls back to scripting secrets/random so attempt #1 of the second create collides, and fails loudly if neither seam was exercised rather than passing vacuously). Unknown code -> tests/test_unknown_code.py (404, no Location, nothing written, distinguishable from 410, non-alphabet codes refused). Click analytics -> tests/test_click_analytics.py (0 at creation, exactly 1 after one redirect with last_clicked_at stamped, 2 after two, unchanged at 0 for the 410 path and untouched by a 404).

Design/implementation mismatches deliberately absorbed and flagged as findings: (1) the README describes a Go binary while the brief mandates the FastAPI TestClient - these tests require a Python ASGI app and will error at collection if none is importable; (2) request field name is 'destination_url' in the README but 'url' in the acceptance criteria, so the suite detects it once per session; (3) error code for non-routable destinations is 'private_destination' in the README and 'destination_not_routable' in the acceptance criteria, so either is accepted; (4) scheme rejection is 'invalid_url' in the README and 'scheme_not_allowed' in the criteria, so a small accepted set is used; (5) the README returns 400 invalid_code for out-of-alphabet codes while the criteria say 404, so that one assertion accepts 400 or 404; (6) Cache-Control: no-store is required by the criteria but absent from the README. Deliberately not covered: punycode/IDNA normalization of homograph hosts, the 503 code_generation_failed exhaustion path, persistence across process restart, the background purge, LINKS_BIND_HOST/PORT and LINKS_LOG_LEVEL behaviour, and real DNS timeout handling (LINKS_DNS_TIMEOUT_MS) since that cannot be exercised without either a sleep or network. Click-count assertions poll a bounded number of times, pumping the event loop with a cheap 404 request instead of sleeping, because the design writes the increment as a background task."}

